"""수동 판정의 직렬화 도우미. 판단은 아래 물음별 기록이며 자동 점수 판정은 하지 않는다."""
import json
from pathlib import Path

B = Path(__file__).parent
Q = json.loads((B/'input-11-14.json').read_text(encoding='utf-8-sig'))
S = {r['key']:r['checks'] for r in json.loads((B/'source-checks-11-14.json').read_text(encoding='utf-8'))}
R = []

def add(i, decision, points, rationale, minimum, partial, notes, proposal, related=(), source_note='', issues=()):
    q=Q[i]
    assert len(notes)==len(q['question']['criteria']), (i,len(notes),len(q['question']['criteria']))
    reviews=[]
    for c,n in zip(q['question']['criteria'],notes):
        verdict='keep'
        for v in ('split','combine','revise'):
            if n.startswith(v+':'):
                verdict=v; n=n[len(v)+1:]; break
        reviews.append({'id':c['id'],'verdict':verdict,'reason':n})
    R.append({'key':q['key'],'decision':decision,'proposed_points':points,'rationale':rationale,
              'minimum_answer':minimum,'partial_credit':partial,'criterion_reviews':reviews,'proposal':proposal,
              'related_keys':[Q[j]['key'] if isinstance(j,int) else j for j in related],
              'source_review':{'references':S[q['key']], 'content_notes':source_note,
                 'scope':'입력의 발문·답안·모든 criterion와 critical_facts 및 requirement 인용을 읽고 대조. 연결된 로컬 출처의 인용 142개는 실제 파일과 바이트 일치를 확인했고 핵심 변경 문단의 주변 문맥도 확인. 공식 PDF 원본·시행공고·시험 적용판본을 이번에 전수 재확인한 것은 아니며 후속 수정 수락 전 별도 확인 필요.'},
              'issues':list(issues)})

